import (
	"encoding/csv"
	"fmt"
	"log"
	"os"
	"strconv"
)
func main() {
	// Load the sales data into a 2D slice
	file, err := os.Open("sales_data.csv")
	if err != nil {
		log.Fatal(err)
	}
	defer file.Close()
	reader := csv.NewReader(file)
	reader.FieldsPerRecord = -1 // allow variable number of fields
	rawCSVdata, err := reader.ReadAll()
	if err != nil {
		log.Fatal(err)
	}
	// Convert the sales data to a matrix
	var salesData [][]float64
	for _, record := range rawCSVdata {
		row := make([]float64, len(record))
		for i, value := range record {
			val, err := strconv.ParseFloat(value, 64)
			if err != nil {
				log.Fatal("Parsing float64 error:", err)
			}
			row[i] = val
		}
		salesData = append(salesData, row)
	}
	// Analyze the sales data to identify any trends or patterns
	fmt.Println("Sales data:")
	fmt.Println(salesData)
	// Load and merge external factors data into the sales data
	consumerData := loadExternalData("consumer_behavior.csv")
	marketData := loadExternalData("market_competition.csv")
	mergedData := mergeData(salesData, consumerData, marketData)
	// Analyze the merged data to identify any correlations or relationships
	fmt.Println("Merged data:")
	fmt.Println(mergedData)
}
// Load external data from a CSV file and return a 2D slice
func loadExternalData(fileName string) [][]float64 {
	file, err := os.Open(fileName)
	if err != nil {
		log.Fatal(err)
	}
	defer file.Close()
	reader := csv.NewReader(file)
	reader.FieldsPerRecord = -1 // allow variable number of fields
	rawCSVdata, err := reader.ReadAll()
	if err != nil {
		log.Fatal(err)
	}
	var data [][]float64
	for _, record := range rawCSVdata {
		row := make([]float64, len(record))
		for i, value := range record {
			val, err := strconv.ParseFloat(value, 64)
			if err != nil {
				log.Fatal("Parsing float64 error:", err)
			}
			row[i] = val
		}
		data = append(data, row)
	}
	return data
}
// Merge the sales data with external factors data and return a 2D slice
func mergeData(salesData [][]float64, consumerData [][]float64, marketData [][]float64) [][]float64 {
	// Merge sales data with consumer behavior data
	var mergedData [][]float64
	for i := 0; i < len(salesData); i++ {
		row := append(salesData[i], consumerData[i]...)
		mergedData = append(mergedData, row)
	}
	// Merge merged data with market competition data
	for i := 0; i < len(mergedData); i++ {
		row := append(mergedData[i], marketData[i]...)
		mergedData[i] = row
	}
	return mergedData
} 
