			operator = "";
			operand = "";
			resultField.value = currentResult;
		}
		function calculateResult() {
			let result;
			switch (operator) {
				case "+":
					result = parseInt(operand) + parseInt(currentResult);
					break;
				case "-":
					result = parseInt(operand) - parseInt(currentResult);
					break;
				case "*":
					result = parseInt(operand) * parseInt(currentResult);
					break;
				case "/":
					result = parseInt(operand) / parseInt(currentResult);
					break;
				default:
					result = currentResult;
			}
			currentResult = result;
			operator = "";
			operand = "";
			resultField.value = currentResult;
		}
		document.addEventListener("keydown", function(event) {
			if (event.key === "Enter") {
				calculateResult();
			} else if (event.key === "Backspace") {
				clearResult();
			} else if (event.key === "+" || event.key === "-" || event.key === "*" || event.key === "/") {
				addToResult(event.key);
			} else if (event.key >= "0" && event.key <= "9") {
				addToResult(event.key);
			}
		});
	</script>
</body>
</html>
```
The JavaScript code defines three variables: `currentResult` (the current value being displayed in the text field), `operator` (the current operator being used for the calculation), and `operand` (the previous value entered before the operator). The `addToResult` function handles adding digits to the current value, as well as setting the operator and operand when an operator button is clicked. The `clearResult` function resets all the variables and clears the text field. The `calculateResult` function performs the actual calculation based on the current operator and operand, and updates the text field with the result.
The `document.addEventListener` function at the bottom of the JavaScript code handles keyboard input. The `Enter` key triggers the `calculateResult` function, the `Backspace` key triggers the `clearResult` function, and the number and operator keys trigger the `addToResult` function.

