func SortJSON(jsonObj interface{}, key string) ([]interface{}, error) {
    // Convert the JSON object to a map[string]interface{}
    m, ok := jsonObj.(map[string]interface{})
    if !ok {
        return nil, fmt.Errorf("invalid JSON object")
    }

    // Find the location of the specified key
    var values []interface{}
    var found bool
    for k, v := range m {
        if k == key {
            found = true
            if v == nil {
                return nil, fmt.Errorf("key has null value")
            }
            switch v.(type) {
            case int, float64:
                values = append(values, v)
            default:
                return nil, fmt.Errorf("key value is not numeric")
            }
        } else {
            switch v.(type) {
            case map[string]interface{}, []interface{}:
                subValues, err := SortJSON(v, key)
                if err != nil {
                    return nil, err
                }
                values = append(values, subValues...)
            }
        }
    }
    if !found {
        return nil, fmt.Errorf("key not found")
    }

    // Sort the values in descending order
    sort.Slice(values, func(i, j int) bool {
        return values[i].(float64) > values[j].(float64)
    })

    // Return the top 3 values
    if len(values) < 3 {
        return values, nil
    }
    return values[:3], nil
}
```
