How can I sort the items in a table in ascending order based on their numerical values in Go code? Also, can you provide the average of the values and the total number of items in the table? And finally, can you ensure that the sequence of numbers is provided without any spaces?
Here is the table:
| Item | Value |
|------|-------|
| A    | 10    |
| B    | 20    |
| C    | 30    |
| D    | 40    |
| E    | 50    |
And here is the Go code to achieve this:
package main
import (
    "fmt"
    "sort"
)
func main() {
    items := map[string]int{
        "A": 10,
        "B": 20,
        "C": 30,
        "D": 40,
        "E": 50,
    }
    // Sort items by value in ascending order
    sortedItems := make([]string, 0, len(items))
    for key := range items {
        sortedItems = append(sortedItems, key)
    }
    sort.Slice(sortedItems, func(i, j int) bool {
        return items[sortedItems[i]] < items[sortedItems[j]]
    })
    // Calculate average and total number of items
    total := 0
    for _, value := range items {
        total += value
    }
    average := float64(total) / float64(len(items))
    // Print sorted items without spaces
    sequence := ""
    for _, key := range sortedItems {
        sequence += fmt.Sprintf("%d", items[key])
    }
    fmt.Println("Sorted items:", sortedItems)
    fmt.Println("Average value:", average)
    fmt.Println("Total number of items:", len(items))
    fmt.Println("Sequence of numbers without spaces:", sequence)
}

