fetch(url)
  .then(response => response.text())
  .then(data => {
    const articleTitles = [];
    const articleUrls = [];
    const parser = new DOMParser();
    const htmlDoc = parser.parseFromString(data, "text/html");
    const articles = htmlDoc.querySelectorAll("article");
